const pageLang=document.documentElement.lang==='en'?'en':'th';
const header=document.querySelector('.site-header'),nav=document.querySelector('.main-nav'),shell=document.querySelector('.mega-shell'),menuToggle=document.querySelector('.menu-toggle');
const mobile=matchMedia('(max-width:760px)'),reduced=matchMedia('(prefers-reduced-motion:reduce)');
let closeTimer,activeMenu=null;
function closeMega(){clearTimeout(closeTimer);document.querySelectorAll('.mega-panel').forEach(p=>{p.hidden=true;if(p.parentElement!==shell)shell.append(p)});nav.querySelectorAll('[data-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));header.classList.remove('has-menu');activeMenu=null}
function openMega(button){clearTimeout(closeTimer);const key=button.dataset.menu;if(activeMenu===key)return;closeMega();activeMenu=key;button.setAttribute('aria-expanded','true');const panel=document.querySelector(`#mega-${key}`);panel.hidden=false;if(mobile.matches)button.after(panel);header.classList.add('has-menu')}
nav.querySelectorAll('[data-menu]').forEach(button=>{button.addEventListener('pointerenter',()=>{if(!mobile.matches)openMega(button)});button.addEventListener('focus',()=>{if(!mobile.matches)openMega(button)});button.addEventListener('click',()=>{if(mobile.matches&&activeMenu===button.dataset.menu)closeMega();else openMega(button)})});
header.addEventListener('pointerleave',()=>{if(!mobile.matches)closeTimer=setTimeout(closeMega,160)});header.addEventListener('pointerenter',()=>clearTimeout(closeTimer));
menuToggle.addEventListener('click',()=>{const open=header.classList.toggle('mobile-open');menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',pageLang==='en'?(open?'Close menu':'Open menu'):(open?'ปิดเมนู':'เปิดเมนู'));menuToggle.textContent=open?'×':'☰';if(!open)closeMega()});
function closeNavigation(){closeMega();header.classList.remove('mobile-open');menuToggle.setAttribute('aria-expanded','false');menuToggle.textContent='☰'}
mobile.addEventListener('change',closeNavigation);header.querySelectorAll('.mega-panel a').forEach(a=>a.addEventListener('click',closeNavigation));document.addEventListener('click',e=>{if(!header.contains(e.target))closeMega()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavigation()});
let scrollPending=false;function updateHeader(){header.classList.toggle('scrolled',scrollY>60);scrollPending=false}addEventListener('scroll',()=>{if(!scrollPending){scrollPending=true;requestAnimationFrame(updateHeader)}},{passive:true});updateHeader();
// Shared page modules
if(document.querySelector('#hero-video')){
const video=document.querySelector('#hero-video'),videoToggle=document.querySelector('#video-toggle');function syncVideo(){videoToggle.textContent=video.paused?'▶':'Ⅱ';videoToggle.setAttribute('aria-label',video.paused?'เล่นวิดีโอ':'หยุดวิดีโอ')};video.addEventListener('play',syncVideo);video.addEventListener('pause',syncVideo);if(reduced.matches){video.autoplay=false;video.pause();syncVideo()};videoToggle.addEventListener('click',()=>{if(video.paused)video.play().catch(()=>{});else video.pause()});
}
Promise.race([document.fonts.ready,new Promise(r=>setTimeout(r,1800))]).then(()=>document.body.classList.add('ready'));
if(!reduced.matches){document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}})},{threshold:.12});document.querySelectorAll('.business-intro>div,.business-intro>p,.about-content,.section-heading,.ir-layout,.center-heading,.esg-layout,.news-heading,.career-layout>div,.purpose-strip h2').forEach(e=>{e.classList.add('reveal');observer.observe(e)});const counters=new IntersectionObserver(entries=>{for(const e of entries){if(!e.isIntersecting)continue;counters.unobserve(e.target);const el=e.target,n=Number(el.dataset.count),start=performance.now();function frame(now){const t=Math.min(1,(now-start)/1450),v=Math.round(Math.abs(n)*(1-Math.pow(1-t,3)));el.textContent=n<0?`(${v.toLocaleString('en-US')})`:v.toLocaleString('en-US');if(t<1)requestAnimationFrame(frame);else el.textContent=el.dataset.final}requestAnimationFrame(frame)}},{threshold:.6});document.querySelectorAll('[data-count]').forEach(el=>counters.observe(el))}
const esg=[{image:'/storage/sustainability/environmental-sustainability/img-1.jpg',link:'/th/sustainability/environmental-sustainability/',text:'ความยั่งยืนด้านสิ่งแวดล้อม'},{image:'/storage/sustainability/social-sustainability-materials/img-1.jpg',link:'/th/sustainability/social-sustainability/',text:'ความยั่งยืนด้านสังคม'},{image:'/storage/banner/banner-cg.jpg',link:'/th/corporate-governance/at-a-glance/',text:'การกำกับดูแลกิจการ'}];
let esgIndex=0;async function selectEsg(index){if(index===esgIndex)return;esgIndex=index;document.querySelectorAll('[data-esg]').forEach(b=>{const on=Number(b.dataset.esg)===index;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});const image=document.querySelector('#esg-image'),item={...esg[index]};if(pageLang==='en')item.text=['Environmental Sustainability','Social Sustainability','Corporate Governance'][index];image.style.opacity='.3';const preload=new Image();preload.src='https://www.btsgroup.co.th'+item.image;try{await preload.decode()}catch{}if(esgIndex!==index)return;image.src=preload.src;image.alt=item.text;document.querySelector('#esg-link').href=new URL(item.link.replace('/th/','/'+pageLang+'/').replace(/^\//,''),new URL('./',import.meta.url)).href;document.querySelector('#esg-caption').textContent=item.text+' ↗';image.style.opacity='1'}document.querySelectorAll('[data-esg]').forEach(b=>{b.addEventListener('click',()=>selectEsg(Number(b.dataset.esg)));b.addEventListener('pointerenter',()=>{if(matchMedia('(hover:hover)').matches)selectEsg(Number(b.dataset.esg))})});
if(document.querySelector('.news-carousel')){
const carousel=document.querySelector('.news-carousel'),carouselButtons=[...document.querySelectorAll('[data-carousel]')];function carouselState(){const max=carousel.scrollWidth-carousel.clientWidth;const step=carousel.querySelector('.news-card:not([hidden])').getBoundingClientRect().width+parseFloat(getComputedStyle(carousel).gap);document.querySelector('#news-page').textContent=String(Math.round(carousel.scrollLeft/step)+1);document.querySelector('#news-total').textContent=String(Math.round(max/step)+1);carouselButtons[0].disabled=carousel.scrollLeft<3;carouselButtons[1].disabled=carousel.scrollLeft>max-3}carouselButtons.forEach(b=>b.addEventListener('click',()=>{const step=carousel.querySelector('.news-card:not([hidden])').getBoundingClientRect().width+parseFloat(getComputedStyle(carousel).gap);carousel.scrollBy({left:Number(b.dataset.carousel)*step,behavior:reduced.matches?'instant':'smooth'})}));carousel.addEventListener('scroll',carouselState,{passive:true});new ResizeObserver(carouselState).observe(carousel);carousel.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();carouselButtons[e.key==='ArrowRight'?1:0].click()}});carouselState();
document.querySelectorAll('[data-news-filter]').forEach(button=>button.addEventListener('click',()=>{const kind=button.dataset.newsFilter;document.querySelectorAll('[data-news-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});carousel.querySelectorAll('.news-card').forEach(c=>c.hidden=c.dataset.newsKind!==kind);carousel.dataset.filtered=kind;carousel.scrollLeft=0;carouselState()}));document.querySelector('[data-news-filter].active')?.click();
}
document.querySelector('.back-top')?.addEventListener('click',()=>scrollTo({top:0,behavior:reduced.matches?'instant':'smooth'}));
const search=document.querySelector('#search-dialog'),input=document.querySelector('#search-input'),results=document.querySelector('#search-results');let pagesPromise,searchVersion=0;document.querySelector('.search-open').addEventListener('click',()=>{closeNavigation();search.showModal();input.focus()});document.querySelector('.search-close').addEventListener('click',()=>search.close());search.addEventListener('click',e=>{if(e.target===search)search.close()});let searchTimer;input.addEventListener('input',()=>{clearTimeout(searchTimer);const version=++searchVersion;searchTimer=setTimeout(()=>findPages(input.value.trim(),version),150)});async function findPages(query,version){results.replaceChildren();const msg=document.createElement('p');if(query.length<2){msg.textContent=pageLang==='en'?'Enter at least 2 characters to search':'เริ่มค้นหาโดยพิมพ์อย่างน้อย 2 ตัวอักษร';results.append(msg);return}msg.textContent=pageLang==='en'?'Searching…':'กำลังค้นหา…';results.append(msg);try{pagesPromise??=fetch(new URL('./site-catalog.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('search');return r.json()}).then(d=>d.pages);const pages=await pagesPromise;if(version!==searchVersion)return;const q=query.toLocaleLowerCase(),matches=pages.filter(p=>p.lang===pageLang&&p.navigable!==false&&(p.title+' '+(p.description||'')).toLocaleLowerCase().includes(q)).slice(0,16);results.replaceChildren();if(!matches.length){msg.textContent=pageLang==='en'?'No matching pages. Try another keyword.':'ไม่พบข้อมูลที่ตรงกับคำค้น ลองค้นหาด้วยคำอื่น';results.append(msg);return}for(const page of matches){const a=document.createElement('a');a.href=page.href;const title=document.createElement('strong');title.textContent=page.title.replace(/\s*\|\s*BTS Group.*$/,'');const desc=document.createElement('small');desc.textContent=(page.description||'').slice(0,180);a.append(title,desc);results.append(a)}}catch{pagesPromise=null;msg.textContent=pageLang==='en'?'Search is unavailable. Please try again.':'ไม่สามารถค้นหาได้ในขณะนี้ กรุณาลองใหม่';results.replaceChildren(msg)}}

document.querySelector('.search-form').addEventListener('submit',e=>{e.preventDefault();clearTimeout(searchTimer);findPages(input.value.trim(),++searchVersion)});

